1.query:
fetch spans
| filter span.name == "POST /invocations" and service.name == "guppi_gpt.DEFAULT"
| summarize runs = count(), by: {bin(start_time, 1h)}

2.query:
fetch spans
| filter span.name == "POST /invocations" and service.name == "guppi_gpt.DEFAULT"
| summarize p50 = percentile(duration, 50), p90 = percentile(duration, 90), by: {bin(start_time, 1h)}

3.query:
fetch spans
| filter span.name == "POST /invocations" and service.name == "guppi_gpt.DEFAULT"
| summarize runs = count(), by: {request_is_failed}

5.query:
fetch spans
| filter startsWith(span.name, "chat ") and service.name == "guppi_gpt.DEFAULT"
| summarize input = sum(gen_ai.usage.input_tokens), output = sum(gen_ai.usage.output_tokens), by: {bin(start_time, 1h)}

6.query:
fetch bizevents
| filter event.type == "guppigpt.reply-feedback"
| summarize votes = count(), by: {vote}
